void DialogControllerAsyncWaiter::GetDialogMode(
    DialogMode* out_dialog_mode) {
  base::RunLoop loop;
  proxy_->GetDialogMode(
      base::BindOnce(
          [](base::RunLoop* loop,
             DialogMode* out_dialog_mode
,
             DialogMode dialog_mode) {*out_dialog_mode = std::move(dialog_mode);
            loop->Quit();
          },
          &loop,
          out_dialog_mode));
  loop.Run();
}

DialogMode DialogControllerAsyncWaiter::GetDialogMode(
    ) {
  DialogMode async_wait_result;
  GetDialogMode(&async_wait_result);
  return async_wait_result;
}




